const fs = require('fs');

// Config grammar: one `key=value` per line. Blank lines, and lines whose first
// non-space character is `#`, are ignored. A value runs to the end of the line,
// so `#` does not begin a comment mid-line. A repeated key takes its last value.
function parseConfig(text) {
  // Null-prototype: keys come from a file that a deploy or an operator may
  // eventually supply, so a key named `__proto__` or `constructor` must not be
  // able to reach Object.prototype.
  const config = Object.create(null);
  for (const [index, line] of text.split('\n').entries()) {
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    // Rejecting these matters more than it looks: slicing on a -1 index would
    // drop the key's last character and swallow the whole line as its value,
    // defining a plausible-looking garbage entry with no error.
    if (eq === -1) {
      throw new Error(`Malformed config on line ${index + 1} (expected key=value): ${trimmed}`);
    }
    const key = trimmed.slice(0, eq).trim();
    if (key === '') {
      throw new Error(`Empty config key on line ${index + 1}: ${trimmed}`);
    }
    config[key] = trimmed.slice(eq + 1).trim();
  }
  return config;
}

function loadConfig(path) {
  // Read once at startup, before anything is serving: the synchronous call
  // costs nothing that matters here and keeps every caller free of a promise.
  let text;
  try {
    text = fs.readFileSync(path, 'utf8');
  } catch (err) {
    throw new Error(`Cannot read config file ${path}: ${err.message}`, { cause: err });
  }
  return parseConfig(text);
}

module.exports = { parseConfig, loadConfig };

const path = require('path');
const { greet } = require('./utils');
const { loadConfig } = require('./config');

// Anchored to the package root rather than process.cwd(): this package declares
// src/index.js as its main, so startup must not depend on the caller's directory.
const CONFIG_PATH = path.join(__dirname, '..', 'app.conf');

function main() {
  let config;
  try {
    config = loadConfig(CONFIG_PATH);
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
  console.log(greet(config.name ?? 'world'));
}

main();

const test = require('node:test');
const assert = require('node:assert');
const path = require('path');
const { parseConfig, loadConfig } = require('../src/config');

test('parses key=value pairs and trims surrounding whitespace', () => {
  const config = parseConfig('name=world\n  greeting =  hi there  \n');
  assert.strictEqual(config.name, 'world');
  assert.strictEqual(config.greeting, 'hi there');
});

test('ignores blank lines and full-line comments', () => {
  const config = parseConfig('# a comment\n\n   \nname=world\n   # indented comment\n');
  assert.deepStrictEqual(Object.keys(config), ['name']);
});

test('rejects a line with no "=" rather than truncating the key', () => {
  // Regression: `indexOf` returning -1 used to yield {DEBU: 'DEBUG'}.
  assert.throws(() => parseConfig('DEBUG'), /Malformed config on line 1/);
  assert.throws(() => parseConfig('name=world\nDEBUG'), /line 2/);
});

test('rejects an empty key', () => {
  assert.throws(() => parseConfig('=value'), /Empty config key on line 1/);
});

test('keeps "#" inside a value, since comments are whole-line only', () => {
  assert.strictEqual(parseConfig('name=world # hi').name, 'world # hi');
});

test('preserves "=" appearing in a value', () => {
  assert.strictEqual(parseConfig('token=a=b=c').token, 'a=b=c');
});

test('a repeated key takes its last value', () => {
  assert.strictEqual(parseConfig('name=first\nname=second').name, 'second');
});

test('a __proto__ key does not reach Object.prototype', () => {
  const config = parseConfig('__proto__=polluted');
  assert.strictEqual(config.__proto__, 'polluted');
  assert.strictEqual({}.polluted, undefined);
  assert.strictEqual(Object.getPrototypeOf({}), Object.prototype);
});

test('loadConfig reads the shipped app.conf', () => {
  const config = loadConfig(path.join(__dirname, '..', 'app.conf'));
  assert.strictEqual(config.name, 'world');
});

test('loadConfig names the path it could not read', () => {
  assert.throws(
    () => loadConfig('/nonexistent/app.conf'),
    /Cannot read config file \/nonexistent\/app\.conf/
  );
});

